import{_ as r,a0 as l,w as o,s,ao as g,I as a,x as n,a1 as p,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"五個 ping 工具的使用實例 | LCTT x X-CMD","titleTemplate":false,"description":"五個 ping 工具的使用實例 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五個 ping 工具的使用實例 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五個 ping 工具的使用實例 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Five Examples Of The ping Utility","title":"五個 ping 工具的使用實例","tag":"201311","desc":""},"relativePath":"201311/Five Examples Of The ping Utility.md","filePath":"[post].md"}'),d={name:"201311/Five Examples Of The ping Utility.md"};function h(m,e,c,u,f,x){const i=l("Link");return o(),s("div",null,[e[11]||(e[11]=g(`<h1 id="五個-ping-工具的使用實例" tabindex="-1">五個 ping 工具的使用實例 <a class="header-anchor" href="#五個-ping-工具的使用實例" aria-label="Permalink to “五個 ping 工具的使用實例”">​</a></h1><h3 id="什麼是-ping-工具" tabindex="-1">什麼是 ping 工具### <a class="header-anchor" href="#什麼是-ping-工具" aria-label="Permalink to “什麼是 ping 工具###”">​</a></h3><p>在講述一些關於ping工具真實直觀的使用實例前，先讓我來介紹一下這個命令列工具及其目的。ping工具通常用來測試一台主機在互聯網協議(IP)網絡內的可達性。其名字源於主動聲納法——在水下創建一個脈衝聲音信號(ping)並偵聽周圍物體的返回信號。該方法同樣生動描述了ping網絡工具的工作原理。ping工具對一台主機發送回應請求然後等待ICMP響應。</p><p>實踐中的ping工具的一些例子：</p><h3 id="查詢主機的ip地址" tabindex="-1">查詢主機的IP地址 <a class="header-anchor" href="#查詢主機的ip地址" aria-label="Permalink to “查詢主機的IP地址”">​</a></h3><p>有時候你需要得到某一台主機的IP地址，如圖一。只需要鍵入ping命令後面跟上要查詢的主機名。</p><pre><code>ping www.omgubuntu.com
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping1.png" alt=""></p><h3 id="查詢正在使用的ping工具的版本信息" tabindex="-1">查詢正在使用的ping工具的版本信息 <a class="header-anchor" href="#查詢正在使用的ping工具的版本信息" aria-label="Permalink to “查詢正在使用的ping工具的版本信息”">​</a></h3><p>用 -V 選項可以用來查詢你手頭上ping工具的版本信息。鍵入下列命令顯示正在使用的ping工具的版本信息。</p><pre><code>ping -V
</code></pre><p>正如你從圖二見到的，我正在使用的是“ping utility,iputils-sss20101006”</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping2.png" alt=""></p><h3 id="自動退出-ping" tabindex="-1">自動退出 ping <a class="header-anchor" href="#自動退出-ping" aria-label="Permalink to “自動退出 ping”">​</a></h3><p>當你用‘ping 主機’命令ping一台機器時，ping自己無法停止，你必需按下CTRL+C強行退出，或者你可以用 -c (count)選項指定發送包的數量。使用-c選項，當網絡管理員(其實普通用户也可以)發送完指定數量的包之後，無需按CTRL+C，ping進程就會自動停止。</p><pre><code>ping -c 13 127.0.0.1
</code></pre><p>上列的命令發送了13個包到我的本地主機上。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping3.png" alt=""></p><p>正如你從圖三看到的，我並沒有按CTRL+C，而ping自動退出了。</p><h3 id="指定數據包之間的時間間隔" tabindex="-1">指定數據包之間的時間間隔 <a class="header-anchor" href="#指定數據包之間的時間間隔" aria-label="Permalink to “指定數據包之間的時間間隔”">​</a></h3><p>你知道ping每秒鐘發送一個數據包嗎？你喜歡快一點還是慢一點？用 -i 選項能指定包之間的時間間隔。用下列命令快速發送或慢速發送包。</p><h3 id="每0-13秒發送一個包" tabindex="-1">每0.13秒發送一個包 <a class="header-anchor" href="#每0-13秒發送一個包" aria-label="Permalink to “每0.13秒發送一個包”">​</a></h3><pre><code>ping -i 0.13
</code></pre><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping4.png" alt=""></p><h3 id="每13秒發送一個包" tabindex="-1">每13秒發送一個包 <a class="header-anchor" href="#每13秒發送一個包" aria-label="Permalink to “每13秒發送一個包”">​</a></h3><pre><code>ping -i 13
</code></pre><h3 id="結合-i-選項和-c-選項" tabindex="-1">結合 -i 選項和 -c 選項 <a class="header-anchor" href="#結合-i-選項和-c-選項" aria-label="Permalink to “結合 -i 選項和 -c 選項”">​</a></h3><pre><code>ping -c 13 -i 3
</code></pre><p>總共花費39秒發出13個數據包，數據包的時間間隔為三秒。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/ping6.png" alt=""></p><hr>`,31)),a("p",null,[e[1]||(e[1]=n("via: ",-1)),p(i,{href:"http://www.unixmen.com/five-examples-ping-utility/"},{default:t(()=>[...e[0]||(e[0]=[n("http://www.unixmen.com/five-examples-ping-utility/",-1)])]),_:1})]),a("p",null,[e[4]||(e[4]=n("譯者：",-1)),p(i,{href:"https://github.com/Luoxcat"},{default:t(()=>[...e[2]||(e[2]=[n("Luoxcat",-1)])]),_:1}),e[5]||(e[5]=n(" 校對：",-1)),p(i,{href:"http://blog.csdn.net/tinyeyeser"},{default:t(()=>[...e[3]||(e[3]=[n("Mr小眼兒",-1)])]),_:1})]),a("p",null,[e[8]||(e[8]=n("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[6]||(e[6]=[n("LCTT",-1)])]),_:1}),e[9]||(e[9]=n(" 原創翻譯，",-1)),p(i,{href:"http://linux.cn/"},{default:t(()=>[...e[7]||(e[7]=[n("Linux中國",-1)])]),_:1}),e[10]||(e[10]=n(" 榮譽推出",-1))])])}const P=r(d,[["render",h]]);export{b as __pageData,P as default};
